import org.springframework.web.servlet.support.RequestContextUtils;

public class ThrottlingInterceptor implements HandlerInterceptor {
    private static final int THRESHOLD = 100; // adjust threshold as needed

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {
        int count = RequestContextUtils.getServletContextAttribute("requestCount", request);
        if (count >= THRESHOLD) {
            response.setStatus(HttpServletResponse.SC_RATE_LIMIT_EXCEEDED);
            response.getWriter().println("Rate limit exceeded. Please try again later.");
            return false;
        }
        // increment request count
        RequestContextUtils.setServletContextAttribute("requestCount", count + 1, request);
        return true;
    }
}
